\connect user_db
DELETE FROM user_schema.user_profiles WHERE id >= 10000;

\connect auth_db
DELETE FROM auth_schema.auth_accounts WHERE id >= 10000;
DELETE FROM auth_schema.refresh_tokens WHERE id >= 10000;
DELETE FROM auth_schema.email_otps WHERE id >= 10000;

\connect store_db
